@Route("contact")
public class ContactView extends VerticalLayout implements BeforeLeaveObserver {

    private final ContactMessageService service;

    private final TextField nameField = new TextField("Name");
    private final EmailField emailField = new EmailField("Email");
    private final TextField phoneField = new TextField("Phone");
    private final TextArea messageField = new TextArea("Message");
    private final Button sendButton = new Button("Send");

    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);

    private final Binder<ContactMessage> binder = new Binder<>(ContactMessage.class);

    public ContactView(ContactMessageService service) {
        this.service = service;

        add(new H1("Contact"));
        add(new RouterLink("About", AboutView.class));

        configureBinder();

        HorizontalLayout actions = new HorizontalLayout(sendButton);
        VerticalLayout form = new VerticalLayout(nameField, emailField, phoneField, messageField, actions);
        form.setPadding(false);
        add(form);

        configureGrid();
        add(grid);

        sendButton.addClickListener(e -> send());
        sendButton.addClickShortcut(Key.ENTER);

        for (var field : new com.vaadin.flow.component.HasValue<?, ?>[] { nameField, emailField, phoneField, messageField }) {
            field.addValueChangeListener(e -> sendButton.setEnabled(true));
        }

        refreshGrid();
    }

    private void configureBinder() {
        binder.forField(nameField)
                .withValidator(value -> !value.isBlank(), "Name is required")
                .bind(ContactMessage::getName, ContactMessage::setName);

        binder.forField(emailField)
                .withValidator(new EmailValidator("Enter a valid e-mail address", true))
                .withValidator(value -> !value.isBlank() || !phoneField.getValue().isBlank(),
                        "Give an e-mail address or a phone number")
                .bind(ContactMessage::getEmail, ContactMessage::setEmail);

        binder.forField(phoneField)
                .bind(ContactMessage::getPhone, ContactMessage::setPhone);

        binder.forField(messageField)
                .withValidator(value -> !value.isBlank(), "Message is required")
                .withValidator(value -> value.length() <= 500, "Message must be at most 500 characters")
                .bind(ContactMessage::getMessage, ContactMessage::setMessage);
    }

