+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.NotificationVariant;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.binder.Binder;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.router.Route;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final ContactMessageService service;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Binder<ContactMessage> binder = new Binder<>(ContactMessage.class);
+
+    public ContactView(ContactMessageService service) {
+        this.service = service;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        configureBinder();
+
+        HorizontalLayout actions = new HorizontalLayout(sendButton);
+        VerticalLayout form = new VerticalLayout(nameField, emailField, phoneField, messageField, actions);
+        form.setPadding(false);
+        add(form);
+
+        configureGrid();
+        add(grid);
+
+        sendButton.addClickListener(e -> send());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        for (HasValue<?, ?> field : new HasValue<?, ?>[] { nameField, emailField, phoneField, messageField }) {
+            field.addValueChangeListener(e -> sendButton.setEnabled(true));
+        }
+
+        refreshGrid();
+    }
+
+    private void configureBinder() {
+        emailField.setI18n(new EmailField.EmailFieldI18n()
+                .setPatternErrorMessage("Enter a valid e-mail address"));
+
+        binder.forField(nameField)
+                .withValidator(value -> !value.isBlank(), "Name is required")
+                .bind(ContactMessage::getName, ContactMessage::setName);
+
+        binder.forField(emailField)
+                .withValidator(value -> !value.isBlank() || !phoneField.getValue().isBlank(),
+                        "Give an e-mail address or a phone number")
+                .bind(ContactMessage::getEmail, ContactMessage::setEmail);
+
+        binder.forField(phoneField)
+                .bind(ContactMessage::getPhone, ContactMessage::setPhone);
+
+        binder.forField(messageField)
+                .withValidator(value -> !value.isBlank(), "Message is required")
+                .withValidator(value -> value.length() <= 500, "Message must be at most 500 characters")
+                .bind(ContactMessage::getMessage, ContactMessage::setMessage);
+    }
+
+    private void configureGrid() {
+        grid.addColumn(ContactMessage::getName).setHeader("Name");
+        grid.addColumn(ContactMessage::getEmail).setHeader("Email");
+        grid.addColumn(ContactMessage::getPhone).setHeader("Phone");
+        grid.addColumn(ContactMessage::getMessage).setHeader("Message");
+    }
+
+    private void refreshGrid() {
+        grid.setItems(service.findAll());
+    }
+
+    private void send() {
+        ContactMessage message = new ContactMessage();
+        if (binder.writeBeanIfValid(message)) {
+            service.add(message);
+            refreshGrid();
+
+            binder.readBean(null);
+
+            Notification notification = Notification.show("Message sent");
+            notification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+
+            sendButton.setEnabled(false);
+        }
+    }
+
+    private boolean isDirty() {
+        return !nameField.isEmpty() || !emailField.isEmpty() || !phoneField.isEmpty() || !messageField.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (isDirty()) {
+            var action = event.postpone();
+            confirmNavigation(action);
+        }
+    }
+
+    private void confirmNavigation(BeforeLeaveEvent.ContinueNavigationAction action) {
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add("You have unsent changes. Leaving now will discard them.");
+
+        Button keepEditing = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
